coins = [4, 3, 1]

def greedy(amount):                  # 큰 동전부터 줄 수 있는 만큼
    n = 0
    for c in coins:
        while amount >= c:
            amount -= c
            n += 1
    return n

def best(amount):                    # 전체 탐색: 4원·3원 개수를 모두 시도
    fewest = amount                  # 1원으로만 주면 amount개
    for x in range(amount // 4 + 1):
        for y in range((amount - 4 * x) // 3 + 1):
            ones = amount - 4 * x - 3 * y
            fewest = min(fewest, x + y + ones)
    return fewest

for money in range(1, 21):
    g, b = greedy(money), best(money)
    if g != b:
        print(f'{money}원: 탐욕 {g}개 / 최적 {b}개')
